<template><ContentWrap><div class="heading"><div><h2>课程日历</h2><span>租户内统一课程安排</span></div><div><el-button @click="load">刷新</el-button><el-button v-hasPermi="['zsjos:course-calendar:manage']" type="primary" @click="openCreate">新增课程</el-button></div></div><el-alert v-if="error" type="error" :title="error" show-icon :closable="false"/><el-calendar v-else v-model="anchor" v-loading="loading"><template #date-cell="{ data }"><div class="date-cell"><strong>{{ dayjs(data.day).date() }}</strong><div v-for="event in eventsFor(data.day)" :key="event.id" class="event"><span>{{ event.courseName }}（{{ event.courseFormLabelSnapshot }}）</span><span><el-button v-hasPermi="['zsjos:course-calendar:manage']" link @click.stop="openEdit(event)">编辑</el-button><el-button v-hasPermi="['zsjos:calendar:notify']" link @click.stop="notifyAll(event)">通知全员</el-button><el-button v-hasPermi="['zsjos:course-calendar:manage']" link type="danger" @click.stop="remove(event.id)">删除</el-button></span></div></div></template></el-calendar><div v-if="linkLoading" role="status">正在定位课程…</div><el-alert v-if="linkError" :title="linkError" type="error" :closable="false"><el-button @click="locateCourse">重试定位</el-button></el-alert></ContentWrap><Dialog v-model="detailVisible" title="课程详情" aria-label="课程详情" width="min(560px, calc(100vw - 24px))"><el-descriptions v-if="linkedCourse" :column="1" border><el-descriptions-item label="课程名称">{{ linkedCourse.courseName }}</el-descriptions-item><el-descriptions-item label="课程时间">{{ dayjs(linkedCourse.startTime).format('YYYY-MM-DD HH:mm') }} — {{ dayjs(linkedCourse.endTime).format('YYYY-MM-DD HH:mm') }}</el-descriptions-item><el-descriptions-item label="课程形式">{{ linkedCourse.courseFormLabelSnapshot }}</el-descriptions-item><el-descriptions-item label="备注">{{ linkedCourse.remark || '无' }}</el-descriptions-item></el-descriptions></Dialog><Dialog v-model="visible" :title="editing ? '编辑课程安排' : '新增课程安排'" width="560px"><el-form :model="form" label-width="90px"><el-form-item label="课程名称" required><el-input v-model="form.courseName" maxlength="200"/></el-form-item><el-form-item label="课程形式" required><el-select v-model="form.courseFormValue" class="!w-100%" :options="dictOptions"/></el-form-item><el-form-item label="课程时间" required><el-date-picker v-model="form.range" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" class="!w-100%"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="2000"/></el-form-item><el-form-item label="附件"><span>请使用统一附件上传能力</span></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></Dialog></template>
<script lang="ts" setup>
import dayjs from 'dayjs'; import { reactive, ref, computed, onMounted, watch, onBeforeUnmount } from 'vue'; import { ContentWrap } from '@/components/ContentWrap'; import { ElMessage, ElMessageBox } from 'element-plus'; import * as CalendarApi from '@/api/zsjos/calendar'; import { DICT_TYPE } from '@/utils/dict'; import { getDictOptions } from '@/utils/dict';
defineOptions({ name: 'ZsjosCourseCalendar' })
const route = useRoute()
const linkedCourse = ref<CalendarApi.CourseCalendarEvent>(), detailVisible = ref(false), linkError = ref(''), linkLoading = ref(false)
let linkSequence = 0
const locateCourse = async () => {
  const sequence = ++linkSequence
  linkedCourse.value = undefined; detailVisible.value = false; linkError.value = ''; linkLoading.value = false
  const raw = route.query.courseId
  if (raw == null) return
  if (typeof raw !== 'string' || !/^[1-9]\d*$/.test(raw) || !Number.isSafeInteger(Number(raw))) { linkError.value = '课程通知链接无效'; return }
  linkLoading.value = true
  try {
    const row = await CalendarApi.getCourseCalendarEvent(Number(raw))
    if (sequence !== linkSequence) return
    linkedCourse.value = row; anchor.value = dayjs(row.startTime).toDate(); detailVisible.value = true; await load()
  } catch (cause) { if (sequence === linkSequence) linkError.value = cause instanceof Error ? cause.message : typeof cause === 'string' ? cause : '课程加载失败，请重试' } finally { if (sequence === linkSequence) linkLoading.value = false }
}
onBeforeUnmount(() => { ++linkSequence })
watch(() => route.query.courseId, () => { void locateCourse() })
onMounted(() => { void locateCourse() })
const anchor=ref(new Date()), events=ref<CalendarApi.CourseCalendarEvent[]>([]), loading=ref(false), error=ref(''), visible=ref(false), saving=ref(false), editing=ref<CalendarApi.CourseCalendarEvent>(); const form=reactive<any>({courseName:'',courseFormValue:'',range:[],remark:''}); const dictOptions=computed(()=>getDictOptions(DICT_TYPE.ZSJOS_COURSE_FORM));
const load=async()=>{loading.value=true; error.value=''; try{events.value=await CalendarApi.getCourseCalendar({rangeStart:dayjs(anchor.value).startOf('month').startOf('week').format('YYYY-MM-DDTHH:mm:ss'),rangeEnd:dayjs(anchor.value).endOf('month').endOf('week').format('YYYY-MM-DDTHH:mm:ss')})}catch(e){error.value='课程日历加载失败'}finally{loading.value=false}}; const eventsFor=(day:string)=>events.value.filter(e=>dayjs(e.startTime).isSame(day,'day')); const openCreate=()=>{editing.value=undefined;Object.assign(form,{courseName:'',courseFormValue:'',range:[],remark:''});visible.value=true}; const openEdit=(e:CalendarApi.CourseCalendarEvent)=>{editing.value=e;Object.assign(form,{courseName:e.courseName,courseFormValue:e.courseFormValue,range:[e.startTime,e.endTime],remark:e.remark||''});visible.value=true}; const save=async()=>{saving.value=true;try{const data={courseName:form.courseName,courseFormValue:form.courseFormValue,startTime:form.range[0],endTime:form.range[1],remark:form.remark}; editing.value?await CalendarApi.updateCourseCalendar(editing.value.id,data):await CalendarApi.createCourseCalendar(data);visible.value=false;await load()}finally{saving.value=false}}; const notifyAll=async(e:CalendarApi.CourseCalendarEvent)=>{try{const r=await CalendarApi.sendCalendarNotification({calendarId:e.id,calendarType:'COURSE',scope:'ALL',title:e.courseName,time:e.startTime,remark:e.remark});ElMessage.success(`已提交全员通知（${r.acceptedCount}人）`)}catch{ElMessage.error('通知发送失败')}}; const remove=async(id:number)=>{await ElMessageBox.confirm('确认删除课程安排？');await CalendarApi.deleteCourseCalendar(id);ElMessage.success('已删除');await load()}; onMounted(load)
</script>
